const upsertPasswordCredential = `-- name: UpsertPasswordCredential :exec

INSERT INTO credential (id, user_id, tenant_id, type, secret_hash, params, label)
VALUES ($1, $2, $3, 'password', $4, $5, $6)
ON CONFLICT (user_id) WHERE type = 'password'
DO UPDATE SET secret_hash = EXCLUDED.secret_hash,
              params      = EXCLUDED.params,
              created_at  = now(),
              last_used_at = NULL
`

type UpsertPasswordCredentialParams struct {
	ID         string
	UserID     string
	TenantID   string
	SecretHash string
	Params     dbtypes.JSONMap
	Label      *string
}

// ---------------------------------------------------------------------------------
// Setting a password
// ---------------------------------------------------------------------------------
// Writes the one password credential a user may have.
//
// ON CONFLICT targets credential_one_password_per_user, the partial unique index that
// enforces "at most one password per user". Doing it as an upsert rather than
// delete-then-insert means a password change cannot leave a user with no credential if
// it fails between the two statements.
func (q *Queries) UpsertPasswordCredential(ctx context.Context, arg UpsertPasswordCredentialParams) error {
	_, err := q.db.Exec(ctx, upsertPasswordCredential,
		arg.ID,
		arg.UserID,
		arg.TenantID,
		arg.SecretHash,
		arg.Params,
		arg.Label,
	)
	return err
}

